import React, { useState } from 'react';
import { useParams, useHistory } from 'react-router-dom';

const Inscripcion = () => {
  const { id } = useParams(); // Obtener el ID del curso desde la URL
  const history = useHistory(); // Para redirigir al usuario después de la inscripción

  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    edad: '',
    ocupacion: '',
  });

  // Manejar los cambios en los campos del formulario
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Enviar los datos al backend para crear la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    const response = await fetch('http://localhost:3001/api/usuarios/inscribirse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...formData,
        cursoId: id, // Enviar el ID del curso seleccionado
      }),
    });

    const data = await response.json();

    if (response.ok) {
      alert('Inscripción exitosa');
      // Redirigir a la página de pago
      history.push(`/pago/${id}`);
    } else {
      alert('Error al inscribirse');
    }
  };

  return (
    <div className="inscripcion">
      <h1>Formulario de Inscripción</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="nombre"
          placeholder="Nombre"
          value={formData.nombre}
          onChange={handleChange}
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
        />
        <input
          type="text"
          name="telefono"
          placeholder="Teléfono"
          value={formData.telefono}
          onChange={handleChange}
        />
        <input
          type="number"
          name="edad"
          placeholder="Edad"
          value={formData.edad}
          onChange={handleChange}
        />
        <input
          type="text"
          name="ocupacion"
          placeholder="Ocupación"
          value={formData.ocupacion}
          onChange={handleChange}
        />
        <button type="submit">Inscribirse</button>
      </form>
    </div>
  );
};

export default Inscripcion;
